WITH params AS ( SELECT DATE '2025-01-01' AS start_month, DATE '2026-07-01' AS end_month_exclusive ), months AS ( SELECT m AS report_month FROM params p CROSS JOIN UNNEST( SEQUENCE( p.start_month, DATE_ADD('month', -1, p.end_month_exclusive), INTERVAL '1' MONTH ) ) AS t(m) ), bte_dedup AS ( SELECT order_uuid, CAST(DATE_TRUNC('month', time_of_event) AS DATE) AS report_month, hft, COALESCE(seat_count, 0) AS seat_count, COALESCE(ticket_fare, 0) AS ticket_fare, TRY_CAST(ELEMENT_AT(travellers_age, 1) AS INTEGER) AS primary_age FROM ( SELECT bte.*, ROW_NUMBER() OVER ( PARTITION BY bte.order_uuid ORDER BY bte.time_of_event DESC ) AS rn FROM transaction.bus_ticket_events bte CROSS JOIN params p WHERE bte.country_code = 'IND' AND bte.event_type = 101 AND bte.order_uuid IS NOT NULL AND bte.time_of_event >= CAST(p.start_month AS TIMESTAMP) AND bte.time_of_event < CAST(p.end_month_exclusive AS TIMESTAMP) ) x WHERE rn = 1 ), bpe_reddeal AS ( SELECT bpe.order_uuid, SUM(bpe.selected_payment_amount) AS red_deal_discount FROM transaction.bus_payment_events bpe CROSS JOIN params p WHERE bpe.country_code = 'IND' AND bpe.event_type = 2 AND bpe.payment_system IN ('OP_SL_OFFER', 'OPOFFER') AND bpe.selected_payment_amount > 0 AND bpe.time_of_event >= CAST(p.start_month AS TIMESTAMP) AND bpe.time_of_event < CAST(p.end_month_exclusive AS TIMESTAMP) GROUP BY bpe.order_uuid ), order_base AS ( SELECT b.report_month, b.order_uuid, b.hft, b.seat_count, b.ticket_fare, b.primary_age, CASE WHEN r.order_uuid IS NOT NULL THEN 1 ELSE 0 END AS has_red_deal, COALESCE(r.red_deal_discount, 0) AS red_deal_discount FROM bte_dedup b LEFT JOIN bpe_reddeal r ON b.order_uuid = r.order_uuid ), monthly_metrics AS ( SELECT report_month, -- 1) Overall SUM(1) AS overall_transactions, SUM(seat_count) AS overall_seat_count, SUM(ticket_fare) AS overall_gmv, SUM(CASE WHEN has_red_deal = 1 THEN 1 ELSE 0 END) AS overall_red_deal_transactions, SUM(red_deal_discount) AS overall_red_deal_discount, -- 2) Overall GenZ (15-27) SUM(CASE WHEN primary_age BETWEEN 15 AND 27 THEN 1 ELSE 0 END) AS overall_genz_transactions, SUM(CASE WHEN primary_age BETWEEN 15 AND 27 THEN seat_count ELSE 0 END) AS overall_genz_seat_count, SUM(CASE WHEN primary_age BETWEEN 15 AND 27 THEN ticket_fare ELSE 0 END) AS overall_genz_gmv, SUM(CASE WHEN primary_age BETWEEN 15 AND 27 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS overall_genz_red_deal_transactions, SUM(CASE WHEN primary_age BETWEEN 15 AND 27 THEN red_deal_discount ELSE 0 END) AS overall_genz_red_deal_discount, -- 3) Overall Student (15-22) SUM(CASE WHEN primary_age BETWEEN 15 AND 22 THEN 1 ELSE 0 END) AS overall_student_transactions, SUM(CASE WHEN primary_age BETWEEN 15 AND 22 THEN seat_count ELSE 0 END) AS overall_student_seat_count, SUM(CASE WHEN primary_age BETWEEN 15 AND 22 THEN ticket_fare ELSE 0 END) AS overall_student_gmv, SUM(CASE WHEN primary_age BETWEEN 15 AND 22 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS overall_student_red_deal_transactions, SUM(CASE WHEN primary_age BETWEEN 15 AND 22 THEN red_deal_discount ELSE 0 END) AS overall_student_red_deal_discount, -- 4) Primo SUM(CASE WHEN hft = 2 THEN 1 ELSE 0 END) AS primo_transactions, SUM(CASE WHEN hft = 2 THEN seat_count ELSE 0 END) AS primo_seat_count, SUM(CASE WHEN hft = 2 THEN ticket_fare ELSE 0 END) AS primo_gmv, SUM(CASE WHEN hft = 2 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS primo_red_deal_transactions, SUM(CASE WHEN hft = 2 THEN red_deal_discount ELSE 0 END) AS primo_red_deal_discount, -- 5) Primo GenZ (15-27) SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 27 THEN 1 ELSE 0 END) AS primo_genz_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 27 THEN seat_count ELSE 0 END) AS primo_genz_seat_count, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 27 THEN ticket_fare ELSE 0 END) AS primo_genz_gmv, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 27 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS primo_genz_red_deal_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 27 THEN red_deal_discount ELSE 0 END) AS primo_genz_red_deal_discount, -- 6) Primo Student (15-22) SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 THEN 1 ELSE 0 END) AS primo_student_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 THEN seat_count ELSE 0 END) AS primo_student_seat_count, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 THEN ticket_fare ELSE 0 END) AS primo_student_gmv, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS primo_student_red_deal_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 THEN red_deal_discount ELSE 0 END) AS primo_student_red_deal_discount, -- 7) Overall seat >=3 SUM(CASE WHEN seat_count >= 3 THEN 1 ELSE 0 END) AS overall_seat_ge_3_transactions, SUM(CASE WHEN seat_count >= 3 THEN seat_count ELSE 0 END) AS overall_seat_ge_3_seat_count, SUM(CASE WHEN seat_count >= 3 THEN ticket_fare ELSE 0 END) AS overall_seat_ge_3_gmv, SUM(CASE WHEN seat_count >= 3 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS overall_seat_ge_3_red_deal_transactions, SUM(CASE WHEN seat_count >= 3 THEN red_deal_discount ELSE 0 END) AS overall_seat_ge_3_red_deal_discount, -- 8) Primo seat >=3 SUM(CASE WHEN hft = 2 AND seat_count >= 3 THEN 1 ELSE 0 END) AS primo_seat_ge_3_transactions, SUM(CASE WHEN hft = 2 AND seat_count >= 3 THEN seat_count ELSE 0 END) AS primo_seat_ge_3_seat_count, SUM(CASE WHEN hft = 2 AND seat_count >= 3 THEN ticket_fare ELSE 0 END) AS primo_seat_ge_3_gmv, SUM(CASE WHEN hft = 2 AND seat_count >= 3 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS primo_seat_ge_3_red_deal_transactions, SUM(CASE WHEN hft = 2 AND seat_count >= 3 THEN red_deal_discount ELSE 0 END) AS primo_seat_ge_3_red_deal_discount, -- 9) Overall GenZ seat >=3 SUM(CASE WHEN primary_age BETWEEN 15 AND 27 AND seat_count >= 3 THEN 1 ELSE 0 END) AS overall_genz_seat_ge_3_transactions, SUM(CASE WHEN primary_age BETWEEN 15 AND 27 AND seat_count >= 3 THEN seat_count ELSE 0 END) AS ov