N 15 AND 22 AND seat_count >= 3 THEN 1 ELSE 0 END) AS primo_student_seat_ge_3_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 AND seat_count >= 3 THEN seat_count ELSE 0 END) AS primo_student_seat_ge_3_seat_count, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 AND seat_count >= 3 THEN ticket_fare ELSE 0 END) AS primo_student_seat_ge_3_gmv, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 AND seat_count >= 3 AND has_red_deal = 1 THEN 1 ELSE 0 END) AS primo_student_seat_ge_3_red_deal_transactions, SUM(CASE WHEN hft = 2 AND primary_age BETWEEN 15 AND 22 AND seat_count >= 3 THEN red_deal_discount ELSE 0 END) AS primo_student_seat_ge_3_red_deal_discount FROM order_base GROUP BY report_month ) SELECT m.report_month, COALESCE(mm.overall_transactions, 0) AS overall_transactions, COALESCE(mm.overall_seat_count, 0) AS overall_seat_count, COALESCE(mm.overall_gmv, 0) AS overall_gmv, COALESCE(mm.overall_red_deal_transactions, 0) AS overall_red_deal_transactions, COALESCE(mm.overall_red_deal_discount, 0) AS overall_red_deal_discount, COALESCE(mm.overall_genz_transactions, 0) AS overall_genz_transactions, COALESCE(mm.overall_genz_seat_count, 0) AS overall_genz_seat_count, COALESCE(mm.overall_genz_gmv, 0) AS overall_genz_gmv, COALESCE(mm.overall_genz_red_deal_transactions, 0) AS overall_genz_red_deal_transactions, COALESCE(mm.overall_genz_red_deal_discount, 0) AS overall_genz_red_deal_discount, COALESCE(mm.overall_student_transactions, 0) AS overall_student_transactions, COALESCE(mm.overall_student_seat_count, 0) AS overall_student_seat_count, COALESCE(mm.overall_student_gmv, 0) AS overall_student_gmv, COALESCE(mm.overall_student_red_deal_transactions, 0) AS overall_student_red_deal_transactions, COALESCE(mm.overall_student_red_deal_discount, 0) AS overall_student_red_deal_discount, COALESCE(mm.primo_transactions, 0) AS primo_transactions, COALESCE(mm.primo_seat_count, 0) AS primo_seat_count, COALESCE(mm.primo_gmv, 0) AS primo_gmv, COALESCE(mm.p